import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        List<String> source = new ArrayList<String>(Arrays.asList("welcome", "finish"));
        Solution.Walkthrough open = Solution.openWalkthrough(source);
        assertFalse(open.isClosed());
        assertEquals(Arrays.asList("welcome", "finish"), open.getCards());
        source.set(0, "changed");
        source.add("extra");
        assertEquals(Arrays.asList("welcome", "finish"), open.getCards());
        expectUnsupported(new Runnable() { public void run() { open.getCards().add("x"); }});

        Solution.Walkthrough closed = Solution.closeWalkthrough(open);
        assertTrue(closed.isClosed());
        assertFalse(open.isClosed());
        assertNotSame(open, closed);
        assertEquals(open.getCards(), closed.getCards());
        assertNotSame(open.getCards(), closed.getCards());

        Solution.Walkthrough closedAgain = Solution.closeWalkthrough(closed);
        assertTrue(closedAgain.isClosed());
        assertNotSame(closed, closedAgain);
        assertEquals(closed.getCards(), closedAgain.getCards());
        assertNotSame(closed.getCards(), closedAgain.getCards());

        Solution.Walkthrough empty = Solution.openWalkthrough(Collections.<String>emptyList());
        assertTrue(empty.getCards().isEmpty());
        assertFalse(empty.isClosed());

        List<Boolean> visibility = new ArrayList<Boolean>(Arrays.asList(Boolean.TRUE, Boolean.TRUE));
        List<Boolean> visibilitySnapshot = new ArrayList<Boolean>(visibility);
        assertTrue(Solution.allVisible(visibility));
        assertEquals(visibilitySnapshot, visibility);
        assertFalse(Solution.allVisible(Arrays.asList(Boolean.TRUE, Boolean.FALSE, Boolean.TRUE)));
        assertTrue(Solution.allVisible(Collections.<Boolean>emptyList()));

        expectIllegal(new Runnable() { public void run() { Solution.openWalkthrough(null); }});
        expectIllegal(new Runnable() { public void run() { Solution.openWalkthrough(Arrays.asList("ok", null)); }});
        expectIllegal(new Runnable() { public void run() { Solution.openWalkthrough(Arrays.asList("")); }});
        expectIllegal(new Runnable() { public void run() { Solution.closeWalkthrough(null); }});
        expectIllegal(new Runnable() { public void run() { Solution.allVisible(null); }});
        expectIllegal(new Runnable() { public void run() { Solution.allVisible(Arrays.asList(Boolean.TRUE, null)); }});
    }

    private static void expectIllegal(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("Expected IllegalArgumentException");
    }
    private static void expectUnsupported(Runnable action) {
        try { action.run(); } catch (UnsupportedOperationException expected) { return; }
        throw new AssertionError("Expected UnsupportedOperationException");
    }
    private static void assertTrue(boolean value) { if (!value) throw new AssertionError("Expected true"); }
    private static void assertFalse(boolean value) { if (value) throw new AssertionError("Expected false"); }
    private static void assertNotSame(Object a, Object b) { if (a == b) throw new AssertionError("Expected distinct objects"); }
    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual))
            throw new AssertionError("Expected " + expected + " but got " + actual);
    }
}

